def word_frequency(text):
    clean_text = ''
    for char in text:
        if 'a' <= char.lower() <= 'z' or char.isspace():
            clean_text += char.lower()

    words = clean_text.split()

    frequency = {}
    i = 0
    while i < len(words):
        word = words[i]
        if word in frequency:
            frequency[word] += 1
        else:
            frequency[word] = 1
        i += 1

    return frequency

