def merge_dictionaries(dict1, dict2):
    """
    Merges two dictionaries. If keys overlap, values from dict2 override dict1.

    Args:
        dict1 (dict): The first dictionary.
        dict2 (dict): The second dictionary.

    Returns:
        dict: A new dictionary containing all key-value pairs from both.
    """
    merged_dict = {}
    for key, value in dict1.items():
        merged_dict[key] = value

    for key, value in dict2.items():
        merged_dict[key] = value

    # Alternative compact solution using dictionary unpacking (more Pythonic)
    # merged_dict = {**dict1, **dict2}

    if len(merged_dict) == len(dict1) + len(dict2):
        print("No overlapping keys found.")
    elif len(merged_dict) < len(dict1) + len(dict2):
        diff = (len(dict1) + len(dict2)) - len(merged_dict)
        print(f"{diff} keys were overridden.")

    return merged_dict

# Example usage:
if __name__ == '__main__':
    d1 = {'a': 1, 'b': 2, 'd': 5}
    d2 = {'b': 3, 'c': 4, 'e': 6}
    result = merge_dictionaries(d1, d2)
    print(f"Merged dictionary: {result}")

    d3 = {'x': 10, 'y': 20}
    d4 = {'z': 30, 'w': 40}
    result_no_overlap = merge_dictionaries(d3, d4)
    print(f"Merged dictionary (no overlap): {result_no_overlap}")

