import math

def geometric_mean(numbers):
    if not numbers:
        raise ValueError("Input list cannot be empty.")

    product = 1.0
    for num in numbers:
        if num <= 0:
            raise ValueError("All numbers must be positive.")
        product *= num

    n = len(numbers)
    result = product ** (1 / n)
    return result

if __name__ == '__main__':
    test_cases = [
        ([2, 8], 4.0),
        ([1, 1, 1], 1.0),
        ([4, 1, 1/16], 0.5),
        ([10], 10.0),
        ([3, 9, 27], 9.0)
    ]

    for numbers_list, expected_mean in test_cases:
        actual_mean = geometric_mean(numbers_list)
        assert abs(actual_mean - expected_mean) < 1e-9, \
            f"For {numbers_list}, expected {expected_mean}, but got {actual_mean}"
        print(f"Test passed for {numbers_list}: {actual_mean}")

    try:
        geometric_mean([])
        print("Test failed: Empty list did not raise an error.")
    except ValueError as e:
        if str(e) == "Input list cannot be empty.":
            print("Test passed: Empty list raised expected error.")
        else:
            print(f"Test failed: Empty list raised unexpected error: {e}")

    try:
        geometric_mean([-1, 2, 3])
        print("Test failed: Negative number did not raise an error.")
    except ValueError as e:
        if str(e) == "All numbers must be positive.":
            print("Test passed: Negative number raised expected error.")
        else:
            print(f"Test failed: Negative number raised unexpected error: {e}")

    try:
        geometric_mean([0, 2, 3])
        print("Test failed: Zero number did not raise an error.")
    except ValueError as e:
        if str(e) == "All numbers must be positive.":
            print("Test passed: Zero number raised expected error.")
        else:
            print(f"Test failed: Zero number raised unexpected error: {e}")

