def capitalize_sentences(text):
    sentences = []
    current_sentence_start = 0
    for i in range(len(text)):
        if text[i] in '.!?':
            sentences.append(text[current_sentence_start : i + 1].strip())
            current_sentence_start = i + 1

    if current_sentence_start < len(text):
        remainder = text[current_sentence_start:].strip()
        if len(remainder) > 0:
            sentences.append(remainder)

    capitalized_sentences = []
    for sentence in sentences:
        if len(sentence) > 0:
            first_char = sentence[0].upper()
            rest_of_sentence = sentence[1:]
            capitalized_sentences.append(first_char + rest_of_sentence)
        else:
            capitalized_sentences.append(sentence)

    result = ' '.join(capitalized_sentences)
    return result

