def run_length_encode(s):
    if not s:
        return ""

    encoded_string = []
    current_char = s[0]
    count = 1

    for i in range(1, len(s)):
        if s[i] == current_char:
            count += 1
        else:
            encoded_string.append(current_char + str(count))
            current_char = s[i]
            count = 1

    encoded_string.append(current_char + str(count))
    result = "".join(encoded_string)
    return result

