def is_valid_url(url: str) -> bool:
    if not isinstance(url, str):
        return False

    min_length = 10
    if len(url) < min_length:
        return False

    starts_with_http = url.startswith('http://')
    starts_with_https = url.startswith('https://')

    if not (starts_with_http or starts_with_https):
        return False

    scheme_end_index = 0
    if starts_with_http:
        scheme_end_index = len('http://')
    elif starts_with_https:
        scheme_end_index = len('https://')

    domain_part = url[scheme_end_index:]

    dot_found = False
    for char_index in range(len(domain_part)):
        if domain_part[char_index] == '.':
            dot_found = True
            break

    if not dot_found:
        return False

    first_dot_index = domain_part.find('.')
    last_char_index = len(domain_part) - 1

    if first_dot_index == 0 or first_dot_index == last_char_index:
        return False

    return True

