def harmonic_mean(numbers):
    if not numbers:
        return 0.0

    reciprocal_sum = 0.0
    for x in numbers:
        if x <= 0:
            raise ValueError("All numbers must be positive")
        reciprocal_sum = reciprocal_sum + (1 / x)

    num_elements = float(len(numbers))
    arithmetic_mean_of_reciprocals = reciprocal_sum / num_elements

    if arithmetic_mean_of_reciprocals == 0:
        return 0.0

    mean_value = 1 / arithmetic_mean_of_reciprocals
    return mean_value

