def hex_to_decimal(hex_string):
    decimal_value = 0
    power = 0
    for digit in reversed(hex_string):
        digit = digit.upper()
        if '0' <= digit <= '9':
            val = int(digit)
        elif 'A' <= digit <= 'F':
            val = ord(digit) - ord('A') + 10
        else:
            raise ValueError("Invalid hexadecimal digit found")
        decimal_value = decimal_value + val * (16 ** power)
        power = power + 1
    return decimal_value

