def has_overlap(meeting1, meeting2):
    start1, end1 = meeting1[0], meeting1[1]
    start2, end2 = meeting2[0], meeting2[1]

    # Check if one meeting starts during the other
    if start1 < end2 and start2 < end1:
        return True

    # Check if one meeting contains the other
    if start1 <= start2 and end1 >= end2:
        return True
    if start2 <= start1 and end2 >= end1:
        return True

    # Check for partial overlap (case 1: meeting2 starts during meeting1)
    if start1 < start2 and start2 < end1:
        return True

    # Check for partial overlap (case 2: meeting1 starts during meeting2)
    if start2 < start1 and start1 < end2:
        return True

    # If none of the above conditions are met, there is no overlap
    return False

