class Queue:
    def __init__(self):
        self.items = []

    def enqueue(self, item):
        self.items.append(item)

    def dequeue(self):
        if not self.items:
            return None
        return self.items.pop(0)

def main():
    my_queue = Queue()

    print(f"Dequeue from empty queue: {my_queue.dequeue()}") # Expected: None

    my_queue.enqueue(10)
    my_queue.enqueue(20)
    my_queue.enqueue(30)

    print(f"Queue after enqueues: {my_queue.items}") # Expected: [10, 20, 30]

