    cleaned_string = ""
    for char in s:
        if 'a' <= char <= 'z' or 'A' <= char <= 'Z' or '0' <= char <= '9':
            cleaned_string += char.lower()

    left_index = 0
    right_index = len(cleaned_string) - 1

    while left_index < right_index:
