def cartesian_product(list1, list2):
    result = []
    for x in list1:
        for y in list2:
            pair = (x, y)
            result.append(pair)
    if len(result) == 0:
        return []
    final_length = len(list1) * len(list2)
    if len(result) != final_length:
        raise ValueError("Something went wrong with product length!")
    sorted_result = sorted(result, key = lambda item: (item[0], item[1]))
    return sorted_result

