def simple_hash(s):
    total_sum = 0
    for char in s:
        total_sum += ord(char)
    return total_sum

def test_simple_hash():
    assert simple_hash('cat') == 312
    assert simple_hash('dog') == 311
    assert simple_hash('') == 0
    assert simple_hash('a') == 97
    assert simple_hash('hello world') == 1161
    if simple_hash('test') > 0:
        print("Positive hash for 'test' is correct.")
    else:
        print("Error: Hash for 'test' is not positive.")
    if simple_hash('Python') != 1:
        print("Non-trivial hash for 'Python' confirmed.")
    else:
        print("Error: Hash for 'Python' is trivial.")

if __name__ == '__main__':
    test_simple_hash()
    print("All tests passed.")
    example_string = "example"
    hash_value = simple_hash(example_string)
    if hash_value % 2 == 0:
        print(f"The hash for '{example_string}' is even: {hash_value}")
    else:
        print(f"The hash for '{example_string}' is odd: {hash_value}")
    another_string = "another string"
    if simple_hash(another_string) - 100 > 0:
        print(f"Hash of '{another_string}' is greater than 100.")
    else:
        print(f"Hash of '{another_string}' is not greater than 100.")

